import java.util.stream.Collectors;
import lombok.Value;

/** One player's boss kills as the hiscores showed them at {@code updatedMillis}. Bosses are sorted, most kills first. */
@Value
public class PlayerTotals
{
	String name;
	List<BossKills> bosses;
	long updatedMillis;

	/** False when no boss reaches the hiscore minimum (5 kills). */
	public boolean hasBossKills()
	{
		return !bosses.isEmpty();
	}

	public int totalKills(Set<BossCategory> categories)
	{
		return bosses.stream()
			.filter(boss -> categories.contains(boss.getCategory()))
			.mapToInt(BossKills::getKills)
			.sum();
	}

	public List<BossKills> topBosses(int count, Set<BossCategory> categories)
	{
		return bosses.stream()
			.filter(boss -> categories.contains(boss.getCategory()))
			.limit(count)
			.collect(Collectors.toList());
	}

	public boolean isStale(long nowMillis, Duration maxAge)
	{
		return nowMillis - updatedMillis > maxAge.toMillis();
	}

	public KillSnapshot snapshot()
	{
		Map<BossCategory, Integer> kills = new EnumMap<>(BossCategory.class);
		for (BossKills boss : bosses)
		{
			kills.merge(boss.getCategory(), boss.getKills(), Integer::sum);
		}
		return new KillSnapshot(updatedMillis, kills);
	}
}

package com.bosshighscore;

import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;
import java.util.function.Consumer;
import javax.inject.Inject;
import javax.inject.Singleton;

/**
 * A search clicked during the cooldown waits here; the latest click wins. It counts down in the panel's status line,
 * then searches when the cooldown is over.
 */
@Singleton
class SearchCountdown
{
	private static final long TICK_MILLIS = 200;

	private final ScheduledExecutorService executor;
	private final BossLookupService lookups;

	private String pendingName;
	private Consumer<String> onStatus;
	private Consumer<String> onSearch;
	private ScheduledFuture<?> ticker;

	@Inject
	SearchCountdown(ScheduledExecutorService executor, BossLookupService lookups)
	{
		this.executor = executor;
		this.lookups = lookups;
	}

	synchronized void searchAfterCooldown(String name, Consumer<String> onStatus, Consumer<String> onSearch)
	{
		this.pendingName = name;
		this.onStatus = onStatus;
		this.onSearch = onSearch;
		if (ticker == null)
		{
			ticker = executor.scheduleAtFixedRate(this::tick, 0, TICK_MILLIS, TimeUnit.MILLISECONDS);
		}
	}

	synchronized void stop()
	{
		if (ticker != null)
		{
			ticker.cancel(false);
			ticker = null;
		}
		pendingName = null;
	}

	private synchronized void tick()
	{
		long remaining = lookups.cooldownRemainingMillis();
		if (remaining > 0)
		{
			onStatus.accept("Looking up " + pendingName + " in " + (remaining + 999) / 1000 + "s...");
			return;
		}

		String name = pendingName;
		Consumer<String> search = onSearch;
		stop();
		search.accept(name);
	}
}

